/* eslint-disable @next/next/no-html-link-for-pages, @next/next/no-img-element */

const makerData: Record<string, { name: string; town: string; category: string; product: string; description: string; capacity: string; image: string; status: string }> = {
  "sample-maker-01": { name: "Sample Uraro Kitchen", town: "Torrijos", category: "Food", product: "Uraro cookies", description: "Sample small-batch arrowroot cookies for the project prototype. This is not a real vendor profile.", capacity: "Up to 120 boxes / week", image: "https://images.unsplash.com/photo-1558961363-fa8fdf82db35?auto=format&fit=crop&w=1200&q=85", status: "Verified sample" },
  "sample-maker-02": { name: "Sample Isla Clay Studio", town: "Boac", category: "Crafts", product: "Handmade pottery", description: "Sample handmade pottery for the project prototype. This is not a real vendor profile.", capacity: "Up to 45 pieces / month", image: "https://images.unsplash.com/photo-1578749556568-bc2c40e68b61?auto=format&fit=crop&w=1200&q=85", status: "Verified sample" },
  "sample-maker-03": { name: "Sample Coconut Grove Co-op", town: "Buenavista", category: "Food", product: "Virgin coconut oil", description: "Sample coconut goods for the project prototype. This is not a real vendor profile.", capacity: "Up to 80 bottles / week", image: "https://images.unsplash.com/photo-1608571423902-eed4a5ad8108?auto=format&fit=crop&w=1200&q=85", status: "Verified sample" },
  "sample-maker-04": { name: "Sample Habing Marinduque", town: "Gasan", category: "Crafts", product: "Woven baskets", description: "Sample woven home goods for the project prototype. This is not a real vendor profile.", capacity: "Up to 30 pieces / month", image: "https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3d/Woven_bamboo.jpg/960px-Woven_bamboo.jpg", status: "Pending sample" },
};

export function generateStaticParams() {
  return Object.keys(makerData).map((id) => ({ id }));
}

export default async function VendorProfilePage({ params }: { params: Promise<{ id: string }> }) {
  const { id } = await params;
  const maker = makerData[id];
  if (!maker) return <main className="simple-page"><header className="simple-header"><a className="brand" href="/"><span className="brand-mark">T</span><span>Tatag<span className="brand-light">Marinduque</span></span></a></header><section className="simple-hero"><p className="eyebrow eyebrow-dark">MAKER PROFILE</p><h1>Profile not found.</h1><p>This sample profile is not available. Browse the directory for available makers.</p><a className="button button-dark" href="/directory">Browse makers <span>→</span></a></section></main>;
  return <main className="simple-page"><header className="simple-header"><a className="brand" href="/"><span className="brand-mark">T</span><span>Tatag<span className="brand-light">Marinduque</span></span></a><a className="simple-back" href="/directory">All makers <span>↗</span></a></header><section className="profile-layout"><div className="profile-image">{ }<img src={maker.image} alt={`${maker.product}, sample product`} /><span>{maker.status}</span></div><div className="profile-details"><p className="eyebrow eyebrow-dark">{maker.category.toUpperCase()} <span className="heading-line" /></p><h1>{maker.name}</h1><p className="profile-town">⌖ {maker.town}, Marinduque</p><p className="profile-description">{maker.description}</p><div className="profile-detail-row"><span>PRODUCT</span><strong>{maker.product}</strong></div><div className="profile-detail-row"><span>CAPACITY</span><strong>{maker.capacity}</strong></div><div className="profile-detail-row"><span>CERTIFICATIONS</span><strong>Not provided in sample data</strong></div><div className="profile-detail-row"><span>CONTACT</span><strong>Not provided in sample data</strong></div>{maker.status.startsWith("Verified") ? <a className="button button-dark profile-quote" href={`/quote/${id}`}>Request a quote <span>→</span></a> : <p className="profile-unavailable">Quote requests are only available for verified makers.</p>}<p className="sample-note"><span className="sample-note-dot" /> Sample profile. Not a real business or DTI verification.</p></div></section><footer className="footer"><a className="brand footer-brand" href="/"><span className="brand-mark">T</span><span>Tatag<span className="brand-light">Marinduque</span></span></a><span>Prototype · Sample data only</span></footer></main>;
}
